<?php
/** Original-name collisions on explicitly disposable storage and database only. */
require __DIR__.'/acceptance-path.php';
use FileWarden\{Repository,PermissionService,StorageService,DocumentService,AuditService,DuplicateContent,ImportNames};
function fwsn_assert($v,$why){if(!$v)throw new RuntimeException($why);}
function fwsn_refuse($fn,$why){try{$fn();}catch(Throwable $e){return$e;}throw new RuntimeException($why);}
global$wpdb;wp_set_current_user(1);$repo=new Repository();$storage=new StorageService(FILEWARDEN_STORAGE_DIR,[ABSPATH],true);$service=new DocumentService($repo,new PermissionService([$repo,'folder']),$storage,new AuditService());
if(getenv('FW_SAME_NAME_VERIFY')==='1'){
 $path=fw_acceptance_path('same-name-fixture.json');$fixture=json_decode(file_get_contents($path),true);$original=$repo->document($fixture['original']);fwsn_assert($original===$fixture['baseline'],'Browser actions changed original metadata');$seen=[];$copies=0;
 foreach($repo->documents((int)$fixture['folder'])as$row){fwsn_assert(!isset($seen[$row['name']]),'An existing filename was reused');$seen[$row['name']]=true;if(str_starts_with($row['name'],pathinfo($fixture['name'],PATHINFO_FILENAME))){$stream=$storage->open($row['storage_key'],(int)$row['size']);fwsn_assert(hash('sha256',stream_get_contents($stream))===$original['sha256'],'Original or copy bytes changed');fclose($stream);++$copies;}}
 file_put_contents(fw_acceptance_path('same-name-integrity.json'),wp_json_encode(['original_unchanged'=>true,'all_names_unique'=>true,'same_content_files_verified'=>$copies],JSON_PRETTY_PRINT));WP_CLI::success('Original metadata/bytes unchanged; '.$copies.' independent same-content files have unique names and verified bytes.');return;
}
$suffix=bin2hex(random_bytes(4));$folder=$service->create_folder('Same-name '.$suffix,0,['type'=>'roles','roles'=>['administrator','contributor','subscriber']]);$name='same-name-'.$suffix.'.txt';$bytes='Same-name original content '.$suffix;$source=tempnam(sys_get_temp_dir(),'fwsn-');file_put_contents($source,$bytes);$store=new ReflectionMethod(DocumentService::class,'store');$store->setAccessible(true);
$original=$store->invoke($service,['name'=>$name,'tmp_name'=>$source],$folder,['type'=>'inherit']);$originalRow=$repo->document($original['id']);$total=fn()=>(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM %i WHERE folder_id=%d',$wpdb->prefix.'filewarden_documents',$folder));
$review=fwsn_refuse(fn()=>$store->invoke($service,['name'=>$name,'tmp_name'=>$source],$folder,['type'=>'inherit']),'Same-name duplicate imported without confirmation');fwsn_assert($review instanceof DuplicateContent,'Same-name check blocked content review');fwsn_assert($review->review['import_name']==='same-name-'.$suffix.'-2.txt'&&$total()===1,'Copy suggestion or review persistence invalid');
// A second user wins the suggested name before confirmation: require another review, never overwrite.
$repo->insert('documents',['uuid'=>wp_generate_uuid4(),'folder_id'=>$folder,'name'=>$review->review['import_name'],'storage_key'=>$storage->put($source,strlen($bytes)),'mime'=>'text/plain','size'=>strlen($bytes),'sha256'=>hash('sha256',$bytes),'policy'=>['type'=>'inherit']]);
$options=['duplicate_proof'=>$review->review['proof'],'import_name'=>$review->review['import_name']];$stale=fwsn_refuse(fn()=>$store->invoke($service,['name'=>$name,'tmp_name'=>$source],$folder,['type'=>'inherit'],$options),'Name race overwrote or silently renamed');fwsn_assert($stale instanceof DuplicateContent&&$stale->review['import_name']==='same-name-'.$suffix.'-3.txt'&&$total()===2,'Name race did not require new review');
$copy=$store->invoke($service,['name'=>$name,'tmp_name'=>$source],$folder,['type'=>'inherit'],['duplicate_proof'=>$stale->review['proof'],'import_name'=>$stale->review['import_name'],'description'=>'Confirmed independent copy']);$copyRow=$repo->document($copy['id']);fwsn_assert($copyRow['name']===$stale->review['import_name']&&$copyRow['uuid']!==$originalRow['uuid']&&$copyRow['storage_key']!==$originalRow['storage_key']&&$copyRow['sha256']===$originalRow['sha256']&&$total()===3,'Independent same-content copy invalid');
fwsn_assert($repo->document($original['id'])===$originalRow,'Original metadata changed');$handle=$storage->open($originalRow['storage_key'],strlen($bytes));fwsn_assert(stream_get_contents($handle)===$bytes,'Original bytes changed');fclose($handle);
file_put_contents($source,'Different bytes '.$suffix);$conflict=fwsn_refuse(fn()=>$store->invoke($service,['name'=>$name,'tmp_name'=>$source],$folder,['type'=>'inherit']),'Different content overwrote original');fwsn_assert($conflict instanceof UnexpectedValueException&&!($conflict instanceof DuplicateContent)&&$total()===3,'Name/content conflicts not distinguished');
$bad=fwsn_refuse(fn()=>$store->invoke($service,['name'=>$name,'tmp_name'=>$source],$folder,['type'=>'inherit'],['import_name'=>'changed.php']),'Extension switch accepted');fwsn_assert($bad instanceof InvalidArgumentException,'Invalid copy-name error');
// Real Media import has the same original basename as the protected existing document.
$uploads=wp_upload_dir();$mediaPath=$uploads['path'].'/'.$name;file_put_contents($mediaPath,$bytes);$media=wp_insert_attachment(['post_title'=>'Same-name fixture','post_mime_type'=>'text/plain','post_status'=>'inherit'],$mediaPath);update_attached_file($media,$mediaPath);
$mediaReview=fwsn_refuse(fn()=>$service->import_media($media,$folder,['type'=>'inherit']),'Same-name Media import bypassed review');fwsn_assert($mediaReview instanceof DuplicateContent,'Media basename blocked duplicate review');$mediaCopy=$service->import_media($media,$folder,['type'=>'inherit'],['duplicate_proof'=>$mediaReview->review['proof'],'import_name'=>$mediaReview->review['import_name']]);fwsn_assert($repo->document($mediaCopy['id'])['name']===$mediaReview->review['import_name']&&$total()===4,'Media confirmed copy failed');
$parent=$service->create_folder('Public level',$folder,['type'=>'public']);$nested=$service->create_folder('Inherited level',$parent,['type'=>'inherit']);
$nestedUuid=wp_generate_uuid4();$retainedUuid=wp_generate_uuid4();file_put_contents($source,$bytes);
foreach([$nestedUuid=>[], $retainedUuid=>[['type'=>'authenticated']]]as$uuid=>$retained)$repo->insert('documents',['uuid'=>$uuid,'folder_id'=>$nested,'name'=>'access-'.$uuid.'.txt','storage_key'=>$storage->put($source,strlen($bytes)),'size'=>strlen($bytes),'sha256'=>hash('sha256',$bytes),'mime'=>'text/plain','policy'=>['type'=>'public'],'retained_rules'=>$retained]);
file_put_contents(fw_acceptance_path('same-name-fixture.json'),wp_json_encode(['folder'=>$folder,'original'=>$original['id'],'name'=>$name,'bytes'=>$bytes,'media'=>$media,'baseline'=>$originalRow,'nested_folder'=>$nested,'nested_document'=>$nestedUuid,'retained_document'=>$retainedUuid],JSON_PRETTY_PRINT));unlink($source);
WP_CLI::success('Restricted folder: same-name content review before collision, reviewed numbered copy, name race re-review, unchanged original, different-content conflict, extension-switch refusal, actual Media duplicate/import passed.');
